WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_b_prop'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '正反比关系', 'kp-trv-b-prop', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "正反比关系"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心心法：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "时间一定，路程与速度成正比；路程一定，速度与时间成反比。这是秒杀绝招。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题目不给具体的路程数值，只给“原速度”、“提速20%”、“迟到/提前几小时”等比例和时间差。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推论"}]}, {"type": "katexBlock", "attrs": {"content": "\\text{S 一定：} \\frac{V_1}{V_2} = \\frac{T_2}{T_1} \\quad ; \\quad \\text{T 一定：} \\frac{S_1}{S_2} = \\frac{V_1}{V_2}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[识别出路程 S 是固定不变的(如同一段上下班路)] --> B[根据题意写出提速前后的速度比 V1:V2]\nB --> C[利用反比关系, 写出时间比 T1:T2 = V2:V1]\nC --> D[计算出时间比例的份数差]\nD --> E[将份数差等价于题目给的真实时间差(如提前1小时)]\nE --> F[求出1份代表多少, 进而求出真实时间, 最后解出路程 S]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 某人上班，如果速度提高 25%，可提前 12 分钟到。求原定时间是多少分钟？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "求速度比：提高 25%(1/4)，所以 V原 : V新 = 4 : 5。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "出时间比：路程一定，时间反比。T原 : T新 = 5 : 4。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "找差值：相差了 5 - 4 = 1 份时间。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "等价真实值：这 1 份刚好等于提前的 12 分钟。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "求目标：原时间占 5 份，所以 T原 = 5 × 12 = 60 分钟。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看到提速直接加减时间：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "有人看到提速25%，就觉得时间减少25%，得出 T×75% = T-12，错！速度提1/4，时间减的是1/5。必须老老实实写出 V的整数比，翻转过来变成 T的整数比，再进行份数运算。"}]}]}]}$$ AS jsonb), NULL, '正反比关系的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "正反比关系"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_b_prop", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
